#!/usr/bin/env bash
# =====================================================================
# PHP2Shell Audit Script (CVE-2026-109618 & CVE-2026-109619)
# Memeriksa apakah versi PHP server aman dari exploit OOM longjmp RCE
# =====================================================================

echo "[*] Memeriksa versi runtime PHP aktif..."
if ! command -v php &>/dev/null; then
  echo "[-] Biner php tidak ditemukan di PATH sistem."
  exit 1
fi

PHP_VERSION=$(php -r 'echo PHP_VERSION;')
echo "[+] Versi PHP terdeteksi: $PHP_VERSION"

# Versi minimum yang aman (Patched):
# PHP 8.2 -> 8.2.35
# PHP 8.3 -> 8.3.36
# PHP 8.4 -> 8.4.27
# PHP 8.5 -> 8.5.12

php -r '
$ver = PHP_VERSION;
$safe_map = [
    "8.2" => "8.2.35",
    "8.3" => "8.3.36",
    "8.4" => "8.4.27",
    "8.5" => "8.5.12",
];
$branch = substr($ver, 0, 3);
if (isset($safe_map[$branch])) {
    if (version_compare($ver, $safe_map[$branch], "<")) {
        echo "[!] PERINGATAN: Versi $ver rentan terhadap PHP2Shell (RCE)!\n";
        echo "[!] Segera upgrade ke minimal versi {$safe_map[$branch]}.\n";
        exit(1);
    } else {
        echo "[+] AMAN: Versi $ver sudah memuat patch keamanan PHP2Shell.\n";
        exit(0);
    }
} else {
    echo "[?] Cabang PHP $branch di luar rilis 8.x aktif (periksa status dukungan vendor).\n";
}
'
